x(/\s*[\r\n]?\s*<div[^\>]+\>\s*[\r\n]\s*/gi,"</p>\r\n<p>");

//去掉不需要的标签
x(/[\r\n]?\<([^\/p][^\<\>]*)?\>[\r\n]?/gi,"");
x(/[\r\n]?\<\/([^p][^\<\>]*)?\>[\r\n]?/gi,"");
//乱码删除
x(/(^\s+)|(\s+)$|(\s+)[\r\n]/gi,"");
x(/(^|[\r\n])(<p>)?[^><]*(\>|&gt;)/gi,"$2");
x(/<p>\s*o([\r\n]|$)/g,'');


//开头是否包含段落截断标识
x(/^(?!(\<p\>))/i,"$1hereispagebreak");

